phi=.88;h=np.arange(0,31);dev=30*phi**h;hl=np.log(.5)/np.log(phi);ax.plot(h,dev,color=ACCENT,lw=2,label='expected deviation');ax.axhline(15,color=WARM,ls='--',label='half of initial deviation');ax.axvline(hl,color=BAD,ls='--');ax.scatter([hl],[15],color=BAD,zorder=3);ax.set_xlabel('forecast horizon (trading days)');ax.set_ylabel('deviation (bp)');ax.set_title(f'Half-life = {hl:.2f} trading days',loc='left');ax.legend(fontsize=7)
